function holeFill(arr) {
    const n = arr.length;
    if (n === 0) return [];

    const result = new Array(n).fill(null);
    const original = arr.slice();

    // Forward pass: fill with nearest left non-null
    let lastNonNull = null;
    for (let i = 0; i < n; i++) {
        if (original[i] !== null) {
            lastNonNull = original[i];
            result[i] = original[i];
        } else if (lastNonNull !== null) {
            result[i] = lastNonNull;
        }
    }

    // Backward pass: fill remaining nulls with nearest right non-null
    // But only if no left non-null exists (ties go to left, so left wins)
    lastNonNull = null;
    for (let i = n - 1; i >= 0; i--) {
        if (original[i] !== null) {
            lastNonNull = original[i];
            result[i] = original[i];
